/* ======================================================
   LOGIN DESKTOP INTEGRATO — SM Produce LTD
   Login + scelta modulo (Apple / Cherry) nella stessa pagina
====================================================== */

$secure = (
    (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ||
    (isset($_SERVER['SERVER_PORT']) && (int)$_SERVER['SERVER_PORT'] === 443) ||
    (!empty($_SERVER['HTTP_X_FORWARDED_PROTO']) && $_SERVER['HTTP_X_FORWARDED_PROTO'] === 'https')
);

session_set_cookie_params([
    'lifetime' => 0,
    'path'     => '/',
    'secure'   => $secure,
    'httponly' => true,
    'samesite' => 'Lax'
]);

if (session_status() === PHP_SESSION_NONE) session_start();

if (!function_exists('ch_front_env')) {
    function ch_front_env(string $key, $default = '') {
        $value = getenv($key);
        if ($value === false || $value === null || $value === '') return $default;
        return $value;
    }
}
if (!function_exists('ch_front_b64u')) {
    function ch_front_b64u(string $data): string {
        return rtrim(strtr(base64_encode($data), '+/', '-_'), '=');
    }
}
if (!function_exists('ch_front_make_cherry_token')) {
    function ch_front_make_cherry_token(array $user, int $ttl = 120): string {
        $secret = (string) ch_front_env('CHERRY_SSO_SECRET', 'CHANGE-ME-CHERRY-SSO-SECRET');
        $now = time();
        $payload = [
            'iat' => $now,
            'exp' => $now + max(30, $ttl),
            'user' => [
                'id' => (int)($user['id'] ?? 0),
                'username' => (string)($user['username'] ?? ''),
                'full_name' => (string)($user['full_name'] ?? ''),
                'avatar' => (string)($user['avatar'] ?? ($user['avatar_url'] ?? '')),
                'avatar_url' => (string)($user['avatar_url'] ?? ($user['avatar'] ?? '')),
                'role' => (string)($user['role'] ?? 'viewer'),
                'permissions' => array_values(array_filter((array)($user['permissions'] ?? []), 'is_string')),
            ],
        ];
        $payload64 = ch_front_b64u(json_encode($payload, JSON_UNESCAPED_SLASHES));
        $sig64 = ch_front_b64u(hash_hmac('sha256', $payload64, $secret, true));
        return $payload64 . '.' . $sig64;
    }
}

if (!empty($_SESSION['user'])) {
    header('Location: /pages/dashboard_report.php');
    exit;
}

require_once __DIR__ . '/../config/app.php';
require_once __DIR__ . '/../config/db_remote.php';

$error = null;
$appChoice = trim($_POST['app_choice'] ?? '');

$loadPermissions = static function(mysqli $db, int $userId): array {
    $perms = [];
    $pstmt = $db->prepare("SELECT permission FROM user_permissions WHERE user_id = ?");
    if ($pstmt) {
        $pstmt->bind_param('i', $userId);
        $pstmt->execute();
        $pres = $pstmt->get_result();
        while ($row = $pres->fetch_assoc()) {
            if (!empty($row['permission'])) $perms[] = $row['permission'];
        }
        $pstmt->close();
    }
    return $perms;
};

$cherryLoginUrl = ch_build_public_url(CHERRY_APP_BASE_PATH . '/auth/login.php');
$cherryReturnTarget = $appChoice === 'time' ? (CHERRY_APP_BASE_PATH . '/time/') : sp_cherry_entry_target();

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $username = trim($_POST['username'] ?? '');
    $password = trim($_POST['password'] ?? '');

    if (!in_array($appChoice, ['apple', 'cherry', 'time'], true)) {
        $error = 'Please select Apple, Cherry or Time first.';
    } elseif ($username === '' || $password === '') {
        $error = 'Please enter username and password.';
    } elseif ($appChoice === 'apple') {
        if (!isset($mysqli) || !($mysqli instanceof mysqli) || $mysqli->connect_error) {
            $error = 'Apple database is currently unavailable.';
        } else {
            $stmt = $mysqli->prepare("SELECT id, username, password_hash, full_name, avatar_url, role FROM users WHERE username = ? AND is_active = 1 LIMIT 1");
            if ($stmt) {
                $stmt->bind_param('s', $username);
                $stmt->execute();
                $user = $stmt->get_result()->fetch_assoc();
                $stmt->close();

                if ($user && password_verify($password, $user['password_hash'])) {
                    $_SESSION['user'] = [
                        'id'          => $user['id'],
                        'username'    => $user['username'],
                        'full_name'   => $user['full_name'],
                        'avatar'      => $user['avatar_url'],
                        'avatar_url'  => $user['avatar_url'],
                        'role'        => $user['role'],
                        'permissions' => $loadPermissions($mysqli, (int)$user['id']),
                        'auth_source' => 'apple',
                    ];
                    session_regenerate_id(true);
                    header('Location: /pages/dashboard_report.php');
                    exit;
                }
                $error = 'Invalid username or password.';
            } else {
                $error = 'Database error.';
            }
        }
    } else {
        $error = 'Cherry and Time credentials are verified directly on the Cherry server.';
    }
}
