<script>
(function(){
  const cards = document.querySelectorAll('.app-card');
  const input = document.getElementById('app_choice');
  const form = document.getElementById('loginForm');
  const returnField = document.getElementById('return_target');
  const cherryLoginUrl = <?= json_encode($cherryLoginUrl) ?>;
  const cherryDefaultTarget = <?= json_encode(sp_cherry_entry_target()) ?>;
  const timeTarget = <?= json_encode(CHERRY_APP_BASE_PATH . '/time/') ?>;
  const defaultAction = form.getAttribute('action') || '';

  cards.forEach(card => {
    card.addEventListener('click', () => {
      cards.forEach(c => c.classList.remove('selected'));
      card.classList.add('selected');
      input.value = card.getAttribute('data-app') || '';
    });
  });

  form.addEventListener('submit', function(e){
    const app = input.value || '';
    if (app === 'cherry' || app === 'time') {
      form.action = cherryLoginUrl;
      returnField.value = app === 'time' ? timeTarget : cherryDefaultTarget;
      return;
    }
    form.action = defaultAction;
    returnField.value = '';
  });
})();
</script>
